SELECT 'faq-3', 'هل توفرون خدمة استقبال من المطار؟', 'نعم، نوفر خدمة استقبال من مطار القاهرة الدولي. سيكون السائق في انتظارك في صالة الوصول لضمان تجربة مريحة وسلسة.', 2
WHERE NOT EXISTS (SELECT 1 FROM cars);
INSERT INTO faqs (id, question, answer, display_order)
SELECT 'faq-4', 'ما هي أنواع السيارات المتاحة لديكم؟', 'لدينا أسطول متنوع يشمل سيارات سيدان حديثة (تويوتا، كيا)، سيارات عائلية (SUV)، وميكروباصات حديثة (HiAce) للمجموعات، بالإضافة إلى سيارات ليموزين للمناسبات الخاصة.', 3
WHERE NOT EXISTS (SELECT 1 FROM cars);
INSERT INTO faqs (id, question, answer, display_order)
SELECT 'faq-5', 'هل يمكن حجز سيارة عائلية للسفر؟', 'بالتأكيد! نوفر سيارات عائلية واسعة ومريحة (مثل كيا كرنفال وتويوتا هايس) لضمان راحة جميع أفراد العائلة مع مساحة كافية للأمتعة.', 4
WHERE NOT EXISTS (SELECT 1 FROM cars);
INSERT INTO route_data (id, title, description, metaTitle, metaDescription, heroImage, priceStart, distance, duration, features, faqs, display_order, fromLabel, toLabel)
SELECT 'damietta-cairo', 'سفر من دمياط إلى القاهرة', 'سافر براحة وأمان من باب منزلك في دمياط إلى أي مكان في القاهرة. سيارات حديثة وسائقين محترفين لضمان أفضل تجربة سفر.', 'توصيل من دمياط للقاهرة | حجز سيارة خاصة بأفضل سعر - وصلني', 'احجز سيارة خاصة من دمياط للقاهرة بأفضل الأسعار. سيارات حديثة ومكيفة، سائقين محترفين، وخدمة من الباب للباب. متاحين 24/7.', '/assets/images/cars/family_cruiser/mitsubishi-xpander-2022-rental-damietta-front-white.jpeg', '1500', '290 كم', '3 ساعات', '["توصيل من الباب للباب","سيارات مكيفة وحديثة","سائقين ذوي خبرة","شحن حقائب مجاني"]', '[{"question":"كم سعر التوصيل من دمياط للقاهرة؟","answer":"تبدأ الأسعار من 1500 جنيه للسيارات السيدان، وتختلف حسب نوع السيارة (SUV أو ميكروباص) ومكان التوصيل في القاهرة."},{"question":"هل الرحلة مباشرة؟","answer":"نعم، الرحلة خاصة ومباشرة من باب منزلك في دمياط إلى وجهتك في القاهرة دون توقف إلا للراحة إذا طلبت ذلك."}]', 0, 'دمياط', 'القاهرة'
WHERE NOT EXISTS (SELECT 1 FROM cars);
INSERT INTO route_data (id, title, description, metaTitle, metaDescription, heroImage, priceStart, distance, duration, features, faqs, display_order, fromLabel, toLabel)
SELECT 'damietta-airport', 'توصيل من دمياط لمطار القاهرة', 'لا تقلق بشأن موعد طائرتك. نضمن لك الوصول إلى مطار القاهرة في الوقت المحدد بكل راحة وهدوء.', 'توصيل مطار القاهرة من دمياط | استقبال وتوديع - وصلني', 'خدمة توصيل مطار القاهرة من دمياط. استقبال وتوصيل 24/7. سيارات عائلية وحقائب كبيرة. احجز الآن واضمن وصولك في الموعد.', '/assets/images/cars/minibus/toyota-hiace-granvia-rental-damietta-front-white.jpeg', '1600', '280 كم', '2.5 - 3 ساعات', '["التزام تام بالمواعيد","سيارات واسعة للحقائب","انتظار في صالة الوصول","متابعة حركة الطيران"]', '[{"question":"هل تنتظرون في حال تأخر الطائرة؟","answer":"نعم، نتابع مواعيد وصول الرحلات وننتظر العميل في حالة تأخر الطائرة دون مصاريف إضافية لفترة معقولة."},{"question":"ما هي السيارات المتاحة للمطار؟","answer":"نوفر سيارات سيدان للعدد القليل، وسيارات عائلية (Mitsubishi Xpander) و ميكروباص (HiAce) للعائلات والحقائب الكثيرة."}]', 1, 'دمياط', 'مطار القاهرة'
WHERE NOT EXISTS (SELECT 1 FROM cars);
INSERT INTO route_data (id, title, description, metaTitle, metaDescription, heroImage, priceStart, distance, duration, features, faqs, display_order, fromLabel, toLabel)
SELECT 'cairo-damietta', 'توصيل من القاهرة إلى دمياط', 'عائد إلى دمياط؟ احجز سيارتك من القاهرة أو المطار واستمتع برحلة عودة مريحة وآمنة.', 'توصيل من القاهرة لدمياط | رحلات عودة مريحة - وصلني', 'تحتاج سيارة من القاهرة لدمياط؟ خدمة توصيل خاصة من أي مكان في القاهرة أو الجيزة إلى باب بيتك في دمياط. احجز الآن.', '/assets/images/cars/sedan/fiat-tipo-rental-damietta-front-blue-grey.jpeg', '1500', '290 كم', '3 ساعات', '["حجز فوري","سائقين محترفين للطرق السريعة","راحة تامة بعد السفر","أسعار ثابتة"]', '[{"question":"كيف يمكنني حجز سيارة من القاهرة؟","answer":"يمكنك الحجز عبر الهاتف أو الواتساب قبل موعد السفر بوقت كافٍ (يفضل 24 ساعة) لضمان توفر السيارة."}]', 2, 'القاهرة', 'دمياط'
WHERE NOT EXISTS (SELECT 1 FROM cars);
